import httpRequest from "@/apis/axios-api";

/** 首页聚合数据响应类型 */
export interface HomeAggregatedData {
  notification?: { code: number; data: { theme: string; content: string } };
  announcement?: { code: number; data: { title: string; content: string } };
  banners?: { code: number; data: { images: Array<{ url: string; link: string }> } };
  judge_status?: { code: number; data: Array<{ name: string; url: string; status: string }> };
  friend_link?: { code: number; data: Array<{ name: string; url: string }> };
  judge_statics?: { code: number; data: { list: unknown[] } };
  checkin_statics?: { code: number; data: { list: unknown[] } };
  daily?: { code: number; data: { time: string; list: unknown[] } };
}

/** 获取首页聚合数据（包含通知、公告、轮播图、评测机状态、友链、统计数据、每日题目） */
export function GetHomeData(): Promise<{ code: number; data: HomeAggregatedData }> {
  return httpRequest({
    url: "/home/data",
    method: "get",
  });
}
