<script setup lang="tsx">
import { ref, onMounted, onUnmounted, computed } from "vue";
import { useRouter } from "vue-router";
import { useUserStore } from "@/stores/user.ts";
import { useBreakpoint } from "@/composables/useBreakpoint";
import Hitokoto from "@/components/Hitokoto.vue";
import { GetWebAnnouncement, GetWebNotification, GetWebBanners, GetJudgeStatusList, GetFriendLinkList } from "@/apis/system.ts";
import { GetHomeData } from "@/apis/home";
import { TryAutoCheckin, GetCachedCheckinStatus, GetCheckinStaticsRecently } from "@/apis/checkin.ts";
import { GetDailyTaskHome, PostDailyTaskClaim, TaskStatus, type UserDailyTask, type DailyTaskHomeResult } from "@/apis/daily-task.ts";
import type { Notification, Announcement, BannerItem, JudgeStatus, FriendLink } from "@/types/system.ts";
import { Compass1Icon, EducationIcon } from "tdesign-icons-vue-next";
import { useCurrentInstance } from "@/util";
import { ShowTextTipsSuccess, ShowTextTipsError, ShowEnhancedAwardTips } from "@/util/tips";
import { createFireworks } from "@/util/fireworks";
import { GetJudgeStaticsRecently } from "@/apis/judge.ts";
import { GetProblemDailyRecently, ProblemAttemptStatus } from "@/apis/problem.ts";
import echarts from "@/util/echarts";

const router = useRouter();
const userStore = useUserStore();
const { isMobile } = useBreakpoint();

const dailyTasks = ref<UserDailyTask[]>([]);
const dailyTaskLoading = ref(false);
const businessDate = ref("");
const secondsUntilTaskRefresh = ref(0);

const isCheckedIn = ref(false);
const checkinDate = ref("");

const { globalProperties } = useCurrentInstance();

let intervalId = -1;
let countdownIntervalId = -1;
const notification = ref<Notification>({
  theme: "info",
  content: "",
});
const announcement = ref<Announcement>({
  title: "",
  content: "",
});
const problemDailies = ref([] as any[]);
const stateLoading = ref(false);
const ojStaticsLoading = ref(false);
const checkinStaticsLoading = ref(false);
const problemDailyLoading = ref(false);
const ojNotifyLoading = ref(false);
const ojAnnouncementLoading = ref(false);

// 延迟渲染 MdPreview，避免 vendor-md chunk（1.8MB）在首屏加载时被下载
// 公告位于首屏外（桌面端在统计图表下方，移动端是第 7 项），延迟 2 秒激活对用户感知无影响
const mdPreviewReady = ref(false);

const bannerImages = ref<BannerItem[]>([]);
const bannerLoading = ref(false);
const bannerLoaded = ref(false);

const judgeStatusLoading = ref(true);
const friendLinkLoading = ref(true);

const judgeStatuses = ref<JudgeStatus[]>([]);
const friendLinks = ref<FriendLink[]>([]);

const statusTagTheme = (status: string) => {
  switch (status) {
    case "success": return "success";
    case "warning": return "warning";
    default: return "default";
  }
};
const statusTagText = (status: string) => {
  switch (status) {
    case "success": return "有效";
    case "warning": return "开发中";
    default: return "失效";
  }
};

const loadJudgeStatuses = async (judgeStatusData?: any) => {
  judgeStatusLoading.value = true;
  try {
    const res = judgeStatusData ?? await GetJudgeStatusList();
    const data = res?.data ?? res;
    if (Array.isArray(data)) {
      judgeStatuses.value = data;
    } else if (res.code === 0 && res.data) {
      judgeStatuses.value = res.data;
    }
  } catch (e) {
    console.error("加载判官状态失败：", e);
  } finally {
    judgeStatusLoading.value = false;
  }
};

const loadFriendLinks = async (friendLinkData?: any) => {
  friendLinkLoading.value = true;
  try {
    const res = friendLinkData ?? await GetFriendLinkList();
    const data = res?.data ?? res;
    if (Array.isArray(data)) {
      friendLinks.value = data;
    } else if (res.code === 0 && res.data) {
      friendLinks.value = res.data;
    }
  } catch (e) {
    console.error("加载友情链接失败：", e);
  } finally {
    friendLinkLoading.value = false;
  }
};

const completedTaskCount = computed(() => {
  return dailyTasks.value.filter(t => t.status === TaskStatus.Claimed).length;
});

const totalTaskCount = computed(() => {
  return dailyTasks.value.length;
});

const formatCountdown = (seconds: number) => {
  const hours = Math.floor(seconds / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  const secs = seconds % 60;
  return `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
};

const handleReloadStatus = async (notificationData?: any) => {
  if (notificationData) {
    notification.value = notificationData.data ?? notificationData;
    return;
  }
  notification.value = await GetWebNotification();
};

const handleClaimTask = async (task: UserDailyTask) => {
  if (task.status === TaskStatus.Claimed) {
    return;
  }

  try {
    const res = await PostDailyTaskClaim(task.id);
    if (res.code === 0) {
      task.status = TaskStatus.Claimed;
      createFireworks({ x: window.innerWidth / 2, y: window.innerHeight / 2 });
      ShowEnhancedAwardTips(globalProperties, res.data, 4000);
    } else {
      ShowTextTipsError(globalProperties, `领取失败: ${res.code}`);
    }
  } catch (e) {
    ShowTextTipsError(globalProperties, "领取奖励失败");
  }
};

const getStepClass = (status: TaskStatus) => {
  switch (status) {
    case TaskStatus.Pending:
      return "pending";
    case TaskStatus.Completed:
      return "completed";
    case TaskStatus.Claimed:
      return "claimed";
    default:
      return "pending";
  }
};

const handleAutoCheckin = async () => {
  if (!userStore.isLogin()) {
    return;
  }

  const userId = userStore.getUserId;

  const cache = GetCachedCheckinStatus(userId);
  if (cache) {
    isCheckedIn.value = cache.is_checked_in;
    checkinDate.value = cache.business_date;
    return;
  }

  try {
    const result = await TryAutoCheckin(userId);
    if (result) {
      isCheckedIn.value = result.is_checked_in;
      checkinDate.value = result.business_date;
      if (result.just_checked_in && result.award) {
        ShowTextTipsSuccess(globalProperties, "签到成功！");
        ShowEnhancedAwardTips(globalProperties, result.award, 4000);
      }
    }
  } catch (e) {
    console.error("自动签到失败：", e);
  }
};

const loadDailyTasks = async () => {
  if (!userStore.isLogin()) {
    return;
  }

  dailyTaskLoading.value = true;
  try {
    const res = await GetDailyTaskHome();
    if (res.code === 0) {
      const result = res.data as DailyTaskHomeResult;
      businessDate.value = result.business_date;
      secondsUntilTaskRefresh.value = result.seconds_until_next || 0;
      if (result.tasks && result.tasks.length > 0) {
        dailyTasks.value = result.tasks;
      }
    }
  } catch (e) {
    console.error("加载每日任务失败：", e);
  } finally {
    dailyTaskLoading.value = false;
  }
};

const startCountdown = () => {
  countdownIntervalId = setInterval(() => {
    if (secondsUntilTaskRefresh.value > 0) {
      secondsUntilTaskRefresh.value--;
    }
  }, 1000);
};

const loadWebAnnouncement = async (announcementData?: any) => {
  try {
    const data = announcementData ? (announcementData.data ?? announcementData) : await GetWebAnnouncement();
    announcement.value.title = data.title;
    announcement.value.content = data.content;
  } catch (e) {
    ShowTextTipsError(globalProperties, "加载公告失败");
    announcement.value = {
      title: "公告加载失败",
      content: "请刷新页面重新获取",
    };
  }
};

const loadWebBanners = async (bannerData?: any) => {
  bannerLoading.value = true;
  try {
    const bannersRes: any = bannerData ?? await GetWebBanners();
    const images = bannersRes?.data?.images ?? bannersRes?.images ?? bannersRes?.data?.data?.images;
    if (images && Object.prototype.toString.call(images) === '[object Array]') {
      bannerImages.value = images.map((item: any) => {
        if (typeof item === "string") {
          return { url: item, link: "" };
        }
        return { url: item.url || "", link: item.link || "" };
      });
    } else {
      bannerImages.value = [];
    }
  } catch (e) {
    console.error("加载banner失败", e);
    bannerImages.value = [];
  } finally {
    bannerLoading.value = false;
    bannerLoaded.value = true;
  }
};

const loadOjStatics = async (staticsData?: any) => {
  const res = staticsData ?? await GetJudgeStaticsRecently();
  if ((res.code !== undefined && res.code !== 0) || !res.data) {
    ShowTextTipsError(globalProperties, "加载OJ统计数据失败");
    return;
  }
  const dataList = res.data?.list ?? res.data;

  var dom = document.getElementById("ojStaticsDiv");
  var myChart = echarts.init(dom, null, {
    renderer: "canvas",
    useDirtyRect: false,
  });
  let dateValues = [];
  let acceptValues = [];
  let attemptValues = [];
  let totalValues = [];
  for (const item of dataList) {
    const date = new Date(item.date);
    const dataDayString = `${date.getMonth() + 1}-${date.getDate()}`;
    dateValues.push(dataDayString);
    // accept is the AC count; attempt from backend = total submissions (includes accepts).
    // For stacking, Attempt series must be non-AC attempts only so that
    // accept + non-AC = total submissions (top of stack).
    acceptValues.push(item.accept);
    attemptValues.push(item.attempt - item.accept);
    totalValues.push(item.attempt);
  }
  let option = {
    tooltip: {
      trigger: "axis",
      axisPointer: {
        type: "cross",
        label: {
          backgroundColor: "#6a7985",
        },
      },
    },
    legend: {
      data: ["Accept", "Unaccept"],
    },
    toolbox: {
      feature: {
        saveAsImage: {},
      },
    },
    xAxis: [
      {
        type: "category",
        boundaryGap: false,
        data: dateValues,
      },
    ],
    yAxis: [
      {
        type: "value",
      },
    ],
    series: [
      {
        name: "Accept",
        type: "line",
        stack: "Total",
        color: "#2ecc71",
        areaStyle: {},
        emphasis: {
          focus: "series",
        },
        data: acceptValues,
      },
      {
        name: "Unaccept",
        type: "line",
        stack: "Total",
        color: "#409EFF",
        label: {
          show: true,
          position: "top",
          formatter: (params: any) => totalValues[params.dataIndex],
        },
        areaStyle: {},
        emphasis: {
          focus: "series",
        },
        data: attemptValues,
      },
    ],
  };

  if (option && typeof option === "object") {
    myChart.setOption(option);
  }
  const resizeObserver = new ResizeObserver(() => {
    myChart.resize();
  });
  resizeObserver.observe(dom!);
};

const loadCheckinStatics = async (staticsData?: any) => {
  const res = staticsData ?? await GetCheckinStaticsRecently();
  if ((res.code !== undefined && res.code !== 0) || !res.data) {
    ShowTextTipsError(globalProperties, "加载签到统计数据失败");
    return;
  }
  const dataList = res.data?.list ?? res.data;

  var dom = document.getElementById("checkinStaticsDiv");
  var myChart = echarts.init(dom, null, {
    renderer: "canvas",
    useDirtyRect: false,
  });
  let dateValues = [];
  let countValues = [];
  for (const item of dataList) {
    const date = new Date(item.date);
    const dataDayString = `${date.getMonth() + 1}-${date.getDate()}`;
    dateValues.push(dataDayString);
    countValues.push(item.count);
  }
  let option = {
    tooltip: {
      trigger: "axis",
      axisPointer: {
        type: "shadow",
      },
    },
    toolbox: {
      feature: {
        saveAsImage: {},
      },
    },
    xAxis: [
      {
        type: "category",
        data: dateValues,
      },
    ],
    yAxis: [
      {
        type: "value",
        minInterval: 1,
      },
    ],
    series: [
      {
        name: "签到人数",
        type: "bar",
        color: "#e6a23c",
        barWidth: "60%",
        label: {
          show: true,
          position: "top",
        },
        emphasis: {
          focus: "series",
        },
        data: countValues,
      },
    ],
  };

  if (option && typeof option === "object") {
    myChart.setOption(option);
  }
  const resizeObserver = new ResizeObserver(() => {
    myChart.resize();
  });
  resizeObserver.observe(dom!);
};

const loadProblemDaily = async (dailyData?: any) => {
  problemDailies.value = [];
  const res = dailyData ?? await GetProblemDailyRecently();
  if (res.code !== undefined && res.code !== 0) {
    ShowTextTipsError(globalProperties, "加载每日问题数据失败");
    return;
  }
  const dailyList = res.data?.list;
  const attemptStatus = res.data?.attempt_status;
  if (dailyList && dailyList.length > 0) {
    dailyList.forEach((item: any) => {
      let theme = "default";
      let tag = "未尝试";
      if (attemptStatus) {
        const status = attemptStatus[item.problem_id];
        if (status) {
          switch (status) {
            case ProblemAttemptStatus.Accept:
              theme = "success";
              tag = "已解决";
              break;
            case ProblemAttemptStatus.Attempt:
              theme = "warning";
              tag = "待解决";
              break;
            default:
              theme = "default";
              tag = "未尝试";
          }
        }
      }

      const title = `${item.title}`;

      problemDailies.value.push({
        key: item.key,
        title: title,
        problemKey: item.problem_key,
        theme: theme,
        tag: tag,
      } as any);
    });
  }
};

onMounted(async () => {
  stateLoading.value = true;
  ojStaticsLoading.value = true;
  checkinStaticsLoading.value = true;
  problemDailyLoading.value = true;
  ojNotifyLoading.value = true;
  ojAnnouncementLoading.value = true;

  // 先尝试聚合接口获取所有公共数据
  let aggregatedData: any = null;
  try {
    const response = await GetHomeData();
    if (response.code === 0 && response.data) {
      aggregatedData = response.data;
    }
  } catch (e) {
    console.warn("聚合接口获取失败，退回为分别请求:", e);
  }

  if (aggregatedData) {
    // 聚合接口成功：分发数据到各个模块
    const promises: Promise<void>[] = [];

    // 通知 + 公告 + 轮播图 + 评测机状态 + 友链（顺序执行，轻量操作）
    promises.push((async () => {
      if (aggregatedData.notification) {
        await handleReloadStatus(aggregatedData.notification);
      }
      ojNotifyLoading.value = false;

      // 通知轮询（保持30秒间隔）
      intervalId = setInterval(() => {
        handleReloadStatus();
      }, 30000);

      if (aggregatedData.announcement) {
        await loadWebAnnouncement(aggregatedData.announcement);
      }
      ojAnnouncementLoading.value = false;

      if (aggregatedData.banners) {
        await loadWebBanners(aggregatedData.banners);
      }
      if (aggregatedData.judge_status) {
        await loadJudgeStatuses(aggregatedData.judge_status);
      }
      if (aggregatedData.friend_link) {
        await loadFriendLinks(aggregatedData.friend_link);
      }
    })());

    // OJ 统计图表
    promises.push((async () => {
      if (aggregatedData.judge_statics) {
        await loadOjStatics(aggregatedData.judge_statics);
      }
      ojStaticsLoading.value = false;
    })());

    // 签到统计图表
    promises.push((async () => {
      if (aggregatedData.checkin_statics) {
        await loadCheckinStatics(aggregatedData.checkin_statics);
      }
      checkinStaticsLoading.value = false;
    })());

    // 每日题目
    promises.push((async () => {
      // 缓存的数据不含 attempt_status（用户相关），登录用户直接调接口获取自己的答题状态
      if (!userStore.isLogin() && aggregatedData.daily) {
        await loadProblemDaily(aggregatedData.daily);
      } else {
        await loadProblemDaily();
      }
      problemDailyLoading.value = false;
    })());

    await Promise.all(promises);
  } else {
    // 聚合接口失败：退回为客户端分别请求（原始逻辑）
    void (async () => {
      await handleReloadStatus();
      ojNotifyLoading.value = false;
      intervalId = setInterval(() => {
        handleReloadStatus();
      }, 30000);
      await loadWebAnnouncement();
      ojAnnouncementLoading.value = false;
      await loadWebBanners();
      await loadJudgeStatuses();
      await loadFriendLinks();
    })();

    void (async () => {
      await loadOjStatics();
      ojStaticsLoading.value = false;
    })();

    void (async () => {
      await loadCheckinStatics();
      checkinStaticsLoading.value = false;
    })();

    void (async () => {
      await loadProblemDaily();
      problemDailyLoading.value = false;
    })();
  }

  if (userStore.isLogin()) {
    await handleAutoCheckin();
    await loadDailyTasks();
    startCountdown();
  }

  stateLoading.value = false;

  // 延迟 2 秒激活 MdPreview 渲染，确保首屏（FCP/LCP）不被 vendor-md chunk 下载阻塞
  // 公告位于首屏外，2 秒延迟对用户感知无影响
  setTimeout(() => { mdPreviewReady.value = true; }, 2000);
});

onUnmounted(() => {
  clearInterval(intervalId);
  clearInterval(countdownIntervalId);
});
</script>

<template>
  <t-loading :loading="stateLoading">
    <!-- ==================== 移动端模板 ==================== -->
    <div v-if="isMobile" class="dida-home-mobile">
      <!-- 1. 通知 -->
      <t-loading :loading="ojNotifyLoading && !stateLoading">
        <t-alert v-if="notification" class="dida-mobile-notification" :theme="notification.theme">
          {{ notification.content }}
        </t-alert>
      </t-loading>

      <!-- 2. 轮播图 -->
      <div class="dida-mobile-swiper-div">
        <t-skeleton v-if="!bannerLoaded" animation="gradient" :row-col="[{ width: '100%', height: '160px' }]" />
        <t-swiper v-else-if="bannerImages.length > 0" class="dida-mobile-swiper">
          <t-swiper-item v-for="(item, idx) in bannerImages" :key="idx">
            <a v-if="item.link" :href="item.link" target="_blank" rel="noopener">
              <img :src="item.url" :alt="'DidaOJ Banner ' + (idx + 1)" class="dida-mobile-swiper-img" :fetchpriority="idx === 0 ? 'high' : 'auto'" />
            </a>
            <img v-else :src="item.url" :alt="'DidaOJ Banner ' + (idx + 1)" class="dida-mobile-swiper-img" :fetchpriority="idx === 0 ? 'high' : 'auto'" />
          </t-swiper-item>
        </t-swiper>
        <div v-else class="dida-mobile-banner-placeholder">
          <t-icon name="image-error" size="36px" />
          <span>暂无热点</span>
        </div>
      </div>

      <!-- 3. 一言 -->
      <Hitokoto class="dida-mobile-hitokoto" />

      <!-- 4. 签到卡片 -->
      <t-card class="dida-mobile-card" :bordered="true">
        <template #header>
          <div class="checkin-header">
            <div class="checkin-title">
              <t-icon name="calendar" size="20px" />
              <span>每日签到</span>
            </div>
            <t-tag v-if="isCheckedIn" theme="success" variant="light" size="small">已签到</t-tag>
            <t-tag v-else theme="default" variant="light" size="small">未签到</t-tag>
          </div>
        </template>
        <template #subtitle>
          <div class="checkin-subtitle">
            <span v-if="checkinDate">{{ checkinDate }}</span>
            <span class="checkin-refresh-hint">
              <t-icon name="time" size="12px" />
              每日 00:00 刷新
            </span>
          </div>
        </template>
        <div v-if="!userStore.isLogin()" class="checkin-empty">
          <t-icon name="user" size="32px" :style="{ color: '#bbb' }" />
          <div>登录后参与签到</div>
        </div>
        <div v-else class="checkin-body">
          <div class="checkin-status">
            <div class="checkin-status-icon">
              <t-icon v-if="isCheckedIn" name="check-circle" size="36px" :style="{ color: '#67c23a' }" />
              <t-icon v-else name="calendar" size="36px" :style="{ color: '#409eff' }" />
            </div>
            <div class="checkin-status-text">
              <div v-if="isCheckedIn" class="checkin-success">今日已签到</div>
              <div v-else class="checkin-waiting">正在自动签到...</div>
              <div v-if="isCheckedIn" class="checkin-hint">签到奖励: +20经验 +1金币</div>
            </div>
          </div>
        </div>
      </t-card>

      <!-- 5. 每日任务 -->
      <t-card class="dida-mobile-card" :bordered="true">
        <template #header>
          <div class="task-header">
            <div class="task-title">
              <t-icon name="precise-monitor" size="20px" />
              <span>每日任务</span>
            </div>
            <div class="task-meta">
              <t-tag v-if="totalTaskCount > 0" theme="primary" variant="light" size="small" shape="round">
                <template #icon><t-icon name="check-circle" size="14px" /></template>
                {{ completedTaskCount }}/{{ totalTaskCount }}
              </t-tag>
            </div>
          </div>
        </template>
        <template #subtitle>
          <div class="task-subtitle">
            <span v-if="businessDate">{{ businessDate }}</span>
            <span v-if="secondsUntilTaskRefresh > 0" class="task-countdown">
              <t-icon name="time" size="12px" />
              {{ formatCountdown(secondsUntilTaskRefresh) }}后刷新
            </span>
          </div>
        </template>
        <t-loading :loading="dailyTaskLoading && !stateLoading">
          <div v-if="!userStore.isLogin()" class="task-empty">
            <t-icon name="user" size="32px" :style="{ color: '#bbb' }" />
            <div>登录后查看每日任务</div>
          </div>
          <div v-else-if="dailyTasks.length === 0" class="task-empty">
            <t-icon name="precise-monitor" size="32px" :style="{ color: '#bbb' }" />
            <div>暂无任务</div>
          </div>
          <template v-else>
            <div class="task-progress-bar-wrap">
              <t-progress
                :percentage="totalTaskCount > 0 ? Math.round(completedTaskCount / totalTaskCount * 100) : 0"
                :color="completedTaskCount === totalTaskCount && totalTaskCount > 0 ? '#67c23a' : '#0052d9'"
                :stroke-width="8"
                size="small"
                :label="false"
              />
              <span class="task-progress-label">{{ completedTaskCount }}/{{ totalTaskCount }} 已完成</span>
            </div>
            <div class="task-list">
              <div
                v-for="task in dailyTasks"
                :key="task.id"
                class="task-item"
                :class="{
                  'task-status-completed': task.status === TaskStatus.Completed,
                  'task-status-claimed': task.status === TaskStatus.Claimed,
                  'task-status-pending': task.status === TaskStatus.Pending,
                }"
              >
                <div class="task-item-left">
                  <div class="task-step-indicator" :class="'step-' + getStepClass(task.status)">
                    <t-icon v-if="task.status === TaskStatus.Claimed" name="check" size="14px" />
                    <t-icon v-else-if="task.status === TaskStatus.Completed" name="star-filled" size="14px" />
                    <span v-else>{{ task.task_index }}</span>
                  </div>
                </div>
                <div class="task-item-center">
